const labels={submitted:'وصل طلبك للمراجعة',quoted:'عرض السعر جاهز',changes_requested:'مطلوب تعديل',approved:'وافقت على التنفيذ',producing:'جاري التنفيذ',ready:'جاهز للاستلام',completed:'تم التسليم',cancelled:'ملغي',declined:'اعتذار عن التنفيذ'};
