const money=n=>new Intl.NumberFormat('ar-EG',{maximumFractionDigits:2}).format(Number(n)||0)+' ج.م';
const time=v=>v?new Date(v).toLocaleString('ar-EG',{timeZone:'Africa/Cairo',dateStyle:'medium',timeStyle:'short'}):'يتحدد في عرض السعر';
const uuid=()=>crypto.randomUUID();
const productId=p=>p.id||p.productId;
