const mapLink=value=>{try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&(['maps.google.com','maps.app.goo.gl'].includes(u.hostname)||['google.com','www.google.com'].includes(u.hostname)&&/^\/maps(?:\/|$)/.test(u.pathname))?u.href:'';}catch{return '';}};
const storefrontHref=id=>'/market?view=printing&printProvider='+encodeURIComponent(id);
const input=(name,title,options={})=>`<label data-question="${esc(title)}" data-hint="${esc(options.hint||'')}" ${options.icon?'data-question-icon="'+esc(options.icon)+'"':''}>${esc(title)}<input name="${name}" ${options.type?'type="'+options.type+'"':''} ${options.required?'required':''} ${options.min!==undefined?'min="'+options.min+'"':''} ${options.max!==undefined?'max="'+options.max+'"':''} ${options.step?'step="'+options.step+'"':''} value="${esc(options.value??'')}" maxlength="${options.maxlength||300}" ${options.accept?'accept="'+options.accept+'"':''}></label>`;
