 function reviewMarkup(){return `${specMarkup(draft.type,specOf())}<div class="printing-summary-grid"><div><small>طريقة الاستلام</small><b>${draft.fulfillment==='delivery'?'توصيل':'استلام من المكان'}</b></div><div><small>الوقت المطلوب</small><b>${esc(draft.preferredAt||'يتفق عليه')}</b></div></div>${draft.address?'<p>'+esc(draft.address)+'</p>':''}${draft.notes?'<p class="printing-note">ملاحظاتك: '+esc(draft.notes)+'</p>':''}<p class="printing-note">إرسال الطلب ما يخصمش فلوس. سعر التنفيذ والتوصيل وميعاد الاستلام هيتعرضوا عليك للموافقة.</p><label class="printing-consent"><input type="checkbox" id="printing-consent" ${draft.consent?'checked':''}>أوافق على مشاركة الملفات والتفاصيل مع ${esc(provider(draft.providerId)?.name||'المكتبة المختارة')} لتجهيز طلبي، وإدارة جوّه للمتابعة.</label>`;}
